// 从 KMS/密钥管理服务动态获取密钥
const keyManager = require('./keyManager');

async function signToken(payload) {
    const { privateKey, keyId } = await keyManager.getSigningKey();

    return jwt.sign(payload, privateKey, {
        algorithm: 'RS256',
        issuer: 'your-auth-server',
        audience: 'your-api',
