# 密钥轮换策略示例
class KeyRotationManager:
    def __init__(self):
        self.active_keys = {}  # {kid: key}
        self.retired_keys = {}  # 已退役但仍在验证期的密钥

    def rotate_keys(self):
        """定期轮换密钥（建议每 30-90 天）"""
        new_kid = generate_uuid()
        new_key = generate_rsa_key(2048)

        # 新密钥激活
        self.active_keys[new_kid] = new_key

        # 旧密钥进入宽限期（允许验证，禁止签发）
        for kid in self.active_keys:
            if kid != new_kid:
                self.retired_keys[kid] = self.active_keys.pop(kid)

        # 清理超过宽限期的密钥（如 24 小时）
        self._cleanup_expired_keys()
