#### 方案三：JWT 安全校验增强

```java
// JWT 解析与校验的完整安全实现
public class JwtValidator {

    public Claims validateToken(String token) {
        try {
            // 1. 先解析未验证的头部获取 kid
            String kid = extractKidFromHeader(token);

            // 2. 根据 kid 获取对应公钥
            PublicKey publicKey = keyStore.getPublicKey(kid);
            if (publicKey == null) {
                throw new InvalidTokenException("Unknown kid: " + kid);
            }

            // 3. 强制指定算法，防止算法混淆攻击
            JwtParser parser = Jwts.parserBuilder()
                .setSigningKey(publicKey)
                .setAllowedClockSkewSeconds(30)  // 允许 30 秒时钟偏移
                .requireIssuer("your-auth-server")
                .requireAudience("your-api")
                .build();

            // 4. 解析并验证
            Claims claims = parser.parseClaimsJws(token).getBody();

            // 5. 额外安全检查
            validateTokenType(claims);      // 检查 token_type
            validateUserStatus(claims);     // 检查用户状态
            validatePermissionVersion(claims); // 检查权限版本

            return claims;

        } catch (JwtException e) {
            // 统一异常处理，避免泄露细节
            throw new InvalidTokenException("Token validation failed");
        }
    }

    private String extractKidFromHeader(String token) {
        // 安全解析 header，不使用自动反序列化
        String[] parts = token.split("\\.");
        byte[] headerBytes = Base64.getUrlDecoder().decode(parts[0]);
        JsonNode header = objectMapper.readTree(headerBytes);
        return header.get("kid").asText();
    }
}
```

