    }

    public boolean confirmDeduct(BusinessActionContext ctx) {
        // Confirm阶段：确认扣减（将冻结转为实际扣减）
        Long productId = (Long) ctx.getActionContext("productId");
        Integer quantity = (Integer) ctx.getActionContext("quantity");
        return inventoryMapper.confirmDeduct(productId, quantity) > 0;
    }

    public boolean cancelDeduct(BusinessActionContext ctx) {
        // Cancel阶段：释放冻结库存
        Long productId = (Long) ctx.getActionContext("productId");
        Integer quantity = (Integer) ctx.getActionContext("quantity");
        return inventoryMapper.releaseFrozenStock(productId, quantity) > 0;
    }
}
```

